// CSD_RATIONALE_BEGIN
// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities.
// It uses a combination of unconstrained and constrained steps to generate the solution.
// The strategy starts by generating an initial token without constraints, then refines the answer using grammar constraints.
// If a dead-end is detected, it rolls back to the last valid prefix and continues.
// The process repeats until a valid solution is found or the maximum number of steps is reached.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  if next == eosToken {
    break;
  }

  // Check if the next token forms a valid arithmetic operation
  var isValidOp := Contains(next, "+") || Contains(next, "-") || Contains(next, "*") || Contains(next, "/");
  if isValidOp {
    generated := generated + [next];
    steps := steps + 1;
  } else {
    // If the next token is not a valid operation, roll back to the last valid prefix
    var rolled := helpers.RollbackToValidPrefix(parser, currentConstrained);
    generated := rolled;
    steps := |rolled|;
  }
}
cost := helpers.cost;

